import { Spacing } from "../../components/helperTypes";
import { airbus as tokens } from "@airbus/design-tokens";

export const spacingToTokenValue: (space: Spacing | undefined) => number = (space) => {
  if (!space) return 0;
  const map: { [key: string]: any } = {
    "quarter-x": tokens.size.spacing[2],
    "half-x": tokens.size.spacing[4],
    "three-quarter-x": tokens.size.spacing[6],
    "1-x": tokens.size.spacing[8],
    "1-and-a-half-x": tokens.size.spacing[12],
    "2-x": tokens.size.spacing[16],
    "3-x": tokens.size.spacing[24],
    "4-x": tokens.size.spacing[32],
    "5-x": tokens.size.spacing[40],
    "6-x": tokens.size.spacing[48],
    "7-x": tokens.size.spacing[56],
    "8-x": tokens.size.spacing[64],
  };
  return map[space];
};